<?php
require_once dirname(__DIR__,2).'/src/media.php';require_method('POST');$u=current_user();$d=request_json();$reaction=$d['reaction']??null;if($reaction!==null&&!in_array($reaction,['Like','Love','Laugh'],true))json_response(['error'=>['code'=>'invalid_reaction','message'=>'Invalid story reaction']],400);
mutate($u,$d,'story.react',function($pdo)use($u,$d,$reaction){$id=$d['id']??'';$q=$pdo->prepare('SELECT * FROM stories WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s||!can_view_story($s,$u['id']))throw new DomainException('Story unavailable');if($reaction===null){$q=$pdo->prepare('DELETE FROM story_reactions WHERE story_id=? AND user_id=?');$q->execute([$id,$u['id']]);}else{$q=$pdo->prepare('INSERT INTO story_reactions(story_id,user_id,reaction,updated_at) VALUES(?,?,?,UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE reaction=VALUES(reaction),updated_at=UTC_TIMESTAMP(6)');$q->execute([$id,$u['id'],$reaction]);}return ['ok'=>true];});
